// Reads the visitor IP that Traefik forwarded and builds today's quota path.
// N8N_PROXY_HOPS=1 is set, so x-forwarded-for carries the real client address.
// A private or missing address means IP detection is broken - the quota must then
// fall back to the system-wide cap instead of silently becoming unlimited.
const headers = $input.first().json.headers || {};
const raw = (headers['x-forwarded-for'] || '').split(',')[0].trim();

const isPrivate = (ip) =>
  !ip ||
  ip.startsWith('10.') ||
  ip.startsWith('192.168.') ||
  ip === '::1' ||
  ip === '127.0.0.1' ||
  /^172\.(1[6-9]|2[0-9]|3[01])\./.test(ip) ||
  /^f[cd]/i.test(ip);

const usable = !isPrivate(raw);
// Firebase keys must not contain . # $ / [ ] - dots and colons are escaped.
const key = usable ? raw.replace(/[.:]/g, '_') : 'unknown';
const date = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' });

return [{ json: { ip: raw, ipUsable: usable, ipKey: key, date } }];

// Turns the raw counters into the QuotaStatus shape the frontend expects
// (see src/app/core/recipe.ts). Per-IP limit 3, system-wide 12 per day.
const PER_IP = 3;
const SYSTEM = 12;

const counters = $input.first().json.body || {};
const meta = $('Resolve client IP and date').first().json;

const total = Number(counters._total || 0);
const used = meta.ipUsable ? Number(counters[meta.ipKey] || 0) : total;

const systemLimitReached = total >= SYSTEM;
const remaining = Math.max(0, Math.min(PER_IP - used, SYSTEM - total));

return [{ json: { remaining, limit: PER_IP, systemLimitReached } }];
